 pause:'<path d="M8 5v14M16 5v14"/>', play:'<path d="m8 4 12 8-12 8z"/>', stop:'<rect x="6" y="6" width="12" height="12" rx="2"/>',
 mark:'<path d="M6 3h12v18l-6-4-6 4Z"/>', clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
